<script setup>
import AppIcon from './AppIcon.vue';import {useMovies} from '../composables/useMovies.js';
defineProps({movie:Object});const {isFavorite,toggleFavorite}=useMovies();const base=import.meta.env.BASE_URL;
</script>
<template><article class="movie-card"><div class="poster-wrap"><RouterLink :to="`/movie/${movie.id}`" class="poster-link" :aria-label="`Details for ${movie.title}`"><img :src="base+movie.poster" :alt="`${movie.title} — original concept poster`" loading="lazy" width="600" height="840"><span class="poster-overlay"><span>Explore film<AppIcon name="arrow"/></span></span></RouterLink><span class="rating"><AppIcon name="star"/>{{movie.rating.toFixed(1)}}</span><button class="save-button" :class="{saved:isFavorite(movie.id)}" @click="toggleFavorite(movie.id)" :aria-pressed="isFavorite(movie.id)" :aria-label="`${isFavorite(movie.id)?'Remove':'Save'} ${movie.title} ${isFavorite(movie.id)?'from':'to'} favorites`"><AppIcon :name="isFavorite(movie.id)?'check':'bookmark'"/></button></div><div class="movie-meta"><span>{{movie.year}}</span><i></i><span>{{movie.genre}}</span><span class="duration">{{movie.duration}} min</span></div><h3><RouterLink :to="`/movie/${movie.id}`">{{movie.title}}</RouterLink></h3><p>{{movie.tagline}}</p></article></template>
